import * as React from "react";
import { useTranslation } from "gatsby-plugin-react-i18next";
import AppLink from "./AppLink";
import { getClaimSnippet } from "../utils/claims";

type Props = {
  snippetKey: string;
  supportHrefOverride?: string;
  supportLabelOverride?: string;
  maxWidthClassName?: string;
};

const cardClassName =
  "rounded-2xl border border-black/10 bg-primary/70 p-5 shadow-sm supports-[backdrop-filter]:bg-purplesemilight/40 supports-[backdrop-filter]:backdrop-blur text-light";

const ClaimEvidencePanel: React.FC<Props> = ({
  snippetKey,
  supportHrefOverride,
  supportLabelOverride,
  maxWidthClassName = "max-w-6xl",
}) => {
  const { t } = useTranslation("claims");
  const snippet = getClaimSnippet(t, snippetKey);

  if (!snippet) {
    return null;
  }

  const supportHref = supportHrefOverride || snippet.supportHref;
  const supportLabel = supportLabelOverride || snippet.supportLabel;
  const labels = {
    eyebrow: t("claims.labels.eyebrow") as string,
    claim: t("claims.labels.claim") as string,
    scope: t("claims.labels.scope") as string,
    context: t("claims.labels.context") as string,
    proof: t("claims.labels.proof") as string,
    limit: t("claims.labels.limit") as string,
    support: t("claims.labels.support") as string,
  };

  return (
    <section className="py-8 sm:py-10">
      <div className={`mx-auto w-full ${maxWidthClassName} px-4 sm:px-6`}>
        <article className={cardClassName}>
          <p className="text-xs font-semibold uppercase tracking-[0.14em] text-secondary">
            {labels.eyebrow}
          </p>
          <h2 className="mt-2 text-2xl sm:text-3xl poppins-regular text-verde">
            {snippet.title}
          </h2>

          <div className="mt-5 rounded-xl border border-white/10 bg-white/5 p-4">
            <p className="text-[11px] uppercase tracking-[0.16em] text-light/50">
              {labels.claim}
            </p>
            <p className="mt-2 text-sm sm:text-base text-light/90 leading-relaxed">
              {snippet.claim}
            </p>
          </div>

          <dl className="mt-4 grid grid-cols-1 gap-4 md:grid-cols-2">
            <div className="rounded-xl border border-white/10 bg-white/5 p-4">
              <dt className="text-[11px] uppercase tracking-[0.16em] text-light/50">
                {labels.scope}
              </dt>
              <dd className="mt-2 text-sm sm:text-base text-light/80">
                {snippet.scope}
              </dd>
            </div>
            <div className="rounded-xl border border-white/10 bg-white/5 p-4">
              <dt className="text-[11px] uppercase tracking-[0.16em] text-light/50">
                {labels.context}
              </dt>
              <dd className="mt-2 text-sm sm:text-base text-light/80">
                {snippet.context}
              </dd>
            </div>
            <div className="rounded-xl border border-white/10 bg-white/5 p-4">
              <dt className="text-[11px] uppercase tracking-[0.16em] text-light/50">
                {labels.proof}
              </dt>
              <dd className="mt-2 text-sm sm:text-base text-light/80">
                {snippet.proof}
              </dd>
            </div>
            <div className="rounded-xl border border-white/10 bg-white/5 p-4">
              <dt className="text-[11px] uppercase tracking-[0.16em] text-light/50">
                {labels.limit}
              </dt>
              <dd className="mt-2 text-sm sm:text-base text-light/80">
                {snippet.limit}
              </dd>
            </div>
          </dl>

          <div className="mt-5">
            <p className="text-[11px] uppercase tracking-[0.16em] text-light/50">
              {labels.support}
            </p>
            <div className="mt-2">
              <AppLink className="underline text-sm text-light/90" to={supportHref}>
                {supportLabel}
              </AppLink>
            </div>
          </div>
        </article>
      </div>
    </section>
  );
};

export default ClaimEvidencePanel;
