import * as React from "react";
import { graphql, type HeadFC, type PageProps } from "gatsby";
import {
  VerticalLandingHeadProvider,
  VerticalLandingPage,
} from "../components/VerticalLandingPage";

const ContractorsPage: React.FC<PageProps> = () => (
  <VerticalLandingPage verticalKey="contractors" />
);

export const Head: HeadFC = ({ data, pageContext }) => (
  <VerticalLandingHeadProvider
    verticalKey="contractors"
    data={data}
    pageContext={pageContext}
  />
);

export default ContractorsPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;
